#!/usr/bin/env python3

import urllib.request
import urllib.error

def check_server():
    try:
        response = urllib.request.urlopen('http://localhost:4000/debug_ui.html')
        if response.getcode() == 200:
            print("SUCCESS: Server is running and debug_ui.html is accessible")
            print(f"Content length: {len(response.read())} bytes")
        else:
            print(f"UNEXPECTED: Server responded with status code {response.getcode()}")
    except urllib.error.URLError as e:
        print(f"ERROR: Server is not accessible - {e}")
        print("Please start the server with: python3 -m http.server 4000")
    except Exception as e:
        print(f"UNEXPECTED ERROR: {e}")

if __name__ == "__main__":
    check_server()

